#include <stdio.h>
#include <stdlib.h>

int *give_me_a_number(void) {
    int *local = (int *)malloc(sizeof(int));
    if (local == NULL) {
        return NULL;
    }
    *local = {v};
    return local;
}

int main(void) {
    int *box = give_me_a_number();
    if (box == NULL) {
        printf("仓库没租到喵\n");
        return 1;
    }
    printf("盒子里装着 %d\n", *box);
    free(box);
    box = NULL;
    printf("还掉之后，牌子也收起来了\n");
    return 0;
}
